+				}
+				callsites = append(callsites, Callsite{
+					File:   filePath,
+					Line:   loc.Range.Start.Line + 1, // 0-based → 1-based
+					Column: loc.Range.Start.Character + 1,
+					Method: "lsp",
+				})
+			}
+			return callsites, nil
+		}
+		// LSP error → fall through to textual
+	}
